-- Files kept in object storage (FR-4.6, NFR-13; later figures, PDFs and attachments). The
-- bytes live in the bucket under object_key; this row says whose file it is, what it is for
-- and whether the virus scan has passed. Keys are generated by the server: safe characters
-- only, no leading slash and no "..". Purpose and scan status are text with a CHECK, as in
-- 000006, so a later slice can widen them. Size limits come from the SRS: photo 2 MB
-- (FR-4.6), figure 5 MB (FR-12.2); the other purposes get theirs from their own slices.
CREATE TABLE stored_files (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_user_id uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    purpose       text NOT NULL CONSTRAINT stored_files_purpose_check
                  CHECK (purpose IN ('photo', 'cover', 'figure', 'pdf', 'attachment')),
    object_key    text NOT NULL CONSTRAINT stored_files_object_key_key UNIQUE
                  CONSTRAINT stored_files_object_key_check
                  CHECK (char_length(object_key) <= 512
                         AND object_key ~ '^[A-Za-z0-9][A-Za-z0-9/._-]*$'
                         AND position('..' IN object_key) = 0),
    content_type  text NOT NULL CONSTRAINT stored_files_content_type_check
                  CHECK (char_length(content_type) <= 100 AND content_type ~ '^[a-z]+/[a-z0-9.+-]+$'),
    size_bytes    bigint NOT NULL CONSTRAINT stored_files_size_bytes_check CHECK (size_bytes > 0),
    width         integer CONSTRAINT stored_files_width_check  CHECK (width > 0),
    height        integer CONSTRAINT stored_files_height_check CHECK (height > 0),
    scan_status   text NOT NULL DEFAULT 'pending' CONSTRAINT stored_files_scan_status_check
                  CHECK (scan_status IN ('pending', 'clean', 'rejected')),
    created_at    timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT stored_files_dimensions_pair CHECK ((width IS NULL) = (height IS NULL)),
    CONSTRAINT stored_files_photo_size  CHECK (purpose <> 'photo'  OR size_bytes <= 2097152),
    CONSTRAINT stored_files_figure_size CHECK (purpose <> 'figure' OR size_bytes <= 5242880)
);
CREATE INDEX stored_files_owner_idx ON stored_files (owner_user_id);

-- Objects waiting to be deleted from the bucket (docs/decisions.md, 2026-10-20). A row
-- trigger fills it whenever a stored_files row goes, also through ON DELETE CASCADE, in the
-- same transaction. The API's cleanup worker deletes the object, then the queue row; a
-- failure keeps the row and records the attempt.
CREATE TABLE storage_deletions (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    object_key      text NOT NULL,
    created_at      timestamptz NOT NULL DEFAULT now(),
    attempts        integer NOT NULL DEFAULT 0 CONSTRAINT storage_deletions_attempts_check CHECK (attempts >= 0),
    last_error      text,
    last_attempt_at timestamptz
);
CREATE INDEX storage_deletions_created_idx ON storage_deletions (created_at);

CREATE FUNCTION queue_stored_file_deletion() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO storage_deletions (object_key) VALUES (OLD.object_key);
    RETURN OLD;
END;
$$;
CREATE TRIGGER stored_files_queue_deletion AFTER DELETE ON stored_files
    FOR EACH ROW EXECUTE FUNCTION queue_stored_file_deletion();
